style:
.tw-cosolar--songshi.resume-paper {
  color: #26342d;
}

.tw-cosolar--songshi.resume-paper .paper-header {
  position: relative;
  align-items: center;
  gap: 7mm;
  margin: 0 0 7mm;
  padding: 0 0 5mm;
  border: none;
  border-bottom: 1px solid #dde6df;
}

.tw-cosolar--songshi.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2.4mm;
  background: #2f6d5f;
  print-color-adjust: exact;
}

.tw-cosolar--songshi.resume-paper .paper-photo {
  order: -1;
  width: 27mm;
  height: 36mm;
  border: 0.6mm solid #fff;
  border-radius: 1.2mm;
  box-shadow: 0 0 0 0.45mm #d9e4dd;
  print-color-adjust: exact;
}

.tw-cosolar--songshi.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef4ef;
  color: #2f6d5f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-cosolar--songshi.resume-paper .paper-name {
  color: #24483c;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.02);
  letter-spacing: 0.08em;
}

.tw-cosolar--songshi.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6d7f74;
}

.tw-cosolar--songshi.resume-paper .paper-role {
  margin-top: 1.3mm;
  color: #2f6d5f;
  font-weight: 600;
}

.tw-cosolar--songshi.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7d8f84;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--songshi.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.3mm 8mm;
  margin-top: 3mm;
  color: #33483d;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--songshi.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--songshi.resume-paper .paper-contact__label {
  color: #7f9187;
}

.tw-cosolar--songshi.resume-paper .paper-section {
  margin-bottom: 4.6mm;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  padding: 1.2mm 3mm;
  background: #f1f4f1;
  border-radius: 1.6mm;
  color: #24483c;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  width: 5mm;
  height: 5mm;
  border: none;
  border-radius: 1.2mm;
  background: #2f6d5f;
  color: #fff;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-section__icon svg {
  width: 60%;
  height: 60%;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-section__body {
  margin-top: 2.2mm;
  padding: 2.8mm 3mm;
  background: #f7f8f6;
  border-radius: 1.6mm;
  color: #33463b;
  print-color-adjust: exact;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-item-title {
  color: #1f332a;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-item-period {
  color: #5d776c;
  font-weight: 600;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-item-sub {
  color: #4b5f55;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-note__tag {
  color: #2f6d5f;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-skill {
  border-bottom-color: #e2e8e2;
}

.tw-cosolar--songshi.resume-paper .paper-section .paper-skill__level {
  color: #2f6d5f;
}

.tw-cosolar--songshi.resume-paper .paper-footer {
  border-top: 1px solid #dde6df;
  color: #72857a;
}
